package tn.esprit.partnerintelligence.job;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import tn.esprit.partnerintelligence.service.InferenceOrchestratorService;@Component public class NightlyScoringJob{ private final InferenceOrchestratorService s; public NightlyScoringJob(InferenceOrchestratorService s){this.s=s;} @Scheduled(cron="0 0 2 * * *") public void run(){ for(long p=1;p<=3;p++) s.run(p);} }